UPDATE public.reading_lessons SET
  title_de = 'Meine Stadt',
  title_en = 'My Town',
  content_de = 'Ich heiße Lena. Ich wohne in Bad Ems. Bad Ems ist eine kleine Stadt am Fluss. Nur 9.000 Menschen wohnen hier. Im Zentrum ist der Marktplatz. Dort ist jeden Mittwoch ein Markt. Die Leute kaufen dort Obst und Gemüse. Am Marktplatz sind eine Bäckerei und eine Apotheke.

Mein Lieblingsort ist der Park. Er ist groß und grün. Dort sind viele Bäume und Blumen. Die Kinder spielen dort gern. Wir haben auch ein Rathaus und eine Kirche. Die Kirche ist sehr alt. Der Bahnhof ist klein. Meine Stadt ist klein, aber schön.',
  content_en = 'My name is Lena. I live in Bad Ems. Bad Ems is a small town on the river. Only 9,000 people live here. In the center is the market square. There is a market there every Wednesday. People buy fruit and vegetables there. On the market square there are a bakery and a pharmacy.

My favorite place is the park. It is big and green. There are many trees and flowers there. The children like playing there. We also have a town hall and a church. The church is very old. The train station is small. My town is small, but beautiful.',
  key_vocabulary = '[{"de":"die Stadt, Städte","en":"town, city"},{"de":"der Fluss, Flüsse","en":"river"},{"de":"der Marktplatz, -plätze","en":"market square"},{"de":"die Bäckerei, -en","en":"bakery"},{"de":"die Apotheke, -n","en":"pharmacy"},{"de":"der Park, -s","en":"park"},{"de":"die Kirche, -n","en":"church"},{"de":"der Bahnhof, -höfe","en":"train station"}]'::jsonb,
  questions = '[{"question_de":"Wo wohnt Lena?","question_en":"Where does Lena live?","answer_de":"Lena wohnt in Bad Ems.","answer_en":"Lena lives in Bad Ems."},{"question_de":"Wie viele Menschen wohnen in Bad Ems?","question_en":"How many people live in Bad Ems?","answer_de":"Nur 9.000 Menschen wohnen dort.","answer_en":"Only 9,000 people live there."},{"question_de":"Wann ist der Markt?","question_en":"When is the market?","answer_de":"Der Markt ist jeden Mittwoch.","answer_en":"The market is every Wednesday."},{"question_de":"Was ist Lenas Lieblingsort?","question_en":"What is Lena''s favorite place?","answer_de":"Ihr Lieblingsort ist der Park.","answer_en":"Her favorite place is the park."}]'::jsonb,
