UPDATE public.reading_lessons SET
  title_de = 'Ich bin Anna',
  title_en = 'I am Anna',
  content_de = 'Hallo! Ich heiße Anna Müller. Ich bin 25 Jahre alt. Ich komme aus Deutschland. Ich wohne in Berlin. Berlin ist die Hauptstadt von Deutschland. Berlin ist eine sehr große Stadt.

Ich bin Studentin. Ich studiere Medizin. Ich lerne jeden Tag viel. Meine Wohnung ist klein. Die Wohnung hat zwei Zimmer. Meine Freundin heißt Lisa.

Ich spreche Deutsch, Englisch und ein bisschen Französisch. Das sind drei Sprachen. Deutsch ist meine Muttersprache. Mein Englisch ist sehr gut.

Ich höre gern Musik. Ich spiele auch Klavier. Am Wochenende treffe ich Freunde. Ich mache gern Sport. Ich schwimme gern im Sommer.

Berlin ist eine tolle Stadt. Ich bin sehr glücklich hier.',
  content_en = 'Hello! My name is Anna Müller. I am 25 years old. I come from Germany. I live in Berlin. Berlin is the capital of Germany. Berlin is a very big city.

I am a student. I study medicine. I learn a lot every day. My apartment is small. The apartment has two rooms. My friend is called Lisa.

I speak German, English and a little French. That is three languages. German is my mother tongue. My English is very good.

I like listening to music. I also play piano. On the weekend I meet friends. I like doing sports. I like swimming in summer.

Berlin is a great city. I am very happy here.',
  key_vocabulary = '[{"de":"heißen","en":"to be called"},{"de":"wohnen","en":"to live"},{"de":"die Hauptstadt","en":"capital city"},{"de":"studieren","en":"to study"},{"de":"die Wohnung","en":"apartment"},{"de":"die Sprache","en":"language"},{"de":"die Muttersprache","en":"mother tongue"},{"de":"das Wochenende","en":"weekend"}]'::jsonb,
  questions = '[{"question_de":"Wie alt ist Anna?","question_en":"How old is Anna?","answer_de":"Anna ist 25 Jahre alt.","answer_en":"Anna is 25 years old."},{"question_de":"Was studiert Anna?","question_en":"What does Anna study?","answer_de":"Anna studiert Medizin.","answer_en":"Anna studies medicine."},{"question_de":"Wie viele Sprachen spricht Anna?","question_en":"How many languages does Anna speak?","answer_de":"Anna spricht drei Sprachen.","answer_en":"Anna speaks three languages."},{"question_de":"Was macht Anna am Wochenende?","question_en":"What does Anna do on the weekend?","answer_de":"Anna trifft am Wochenende Freunde.","answer_en":"Anna meets friends on the weekend."}]'::jsonb,
