UPDATE public.reading_lessons SET
  title_de = 'Meine Familie',
  title_en = 'My Family',
  content_de = 'Das ist meine Familie. Meine Familie ist groß. Wir sind neun Personen.

Mein Vater heißt Thomas. Er ist 54 Jahre alt. Er ist Ingenieur. Er arbeitet viel.

Meine Mutter heißt Sabine. Sie ist 51 Jahre alt. Sie ist Lehrerin. Sie kocht sehr gut.

Mein Bruder heißt Max. Er ist 28 Jahre alt. Er ist Arzt. Seine Frau heißt Julia. Ihr Baby heißt Leon.

Meine Schwester heißt Sophie. Sie ist 19 Jahre alt. Sie studiert Kunst.

Meine Großeltern heißen Heinrich und Margarete. Sie haben einen großen Garten.

Am Sonntag sind wir zusammen. Ich liebe meine Familie sehr.',
  content_en = 'This is my family. My family is big. We are nine people.

My father is called Thomas. He is 54 years old. He is an engineer. He works a lot.

My mother is called Sabine. She is 51 years old. She is a teacher. She cooks very well.

My brother is called Max. He is 28 years old. He is a doctor. His wife is called Julia. Their baby is called Leon.

My sister is called Sophie. She is 19 years old. She studies art.

My grandparents are called Heinrich and Margarete. They have a big garden.

On Sunday we are together. I love my family very much.',
  key_vocabulary = '[{"de":"die Familie","en":"family"},{"de":"der Vater","en":"father"},{"de":"die Mutter","en":"mother"},{"de":"der Bruder","en":"brother"},{"de":"die Schwester","en":"sister"},{"de":"die Großeltern","en":"grandparents"},{"de":"der Garten","en":"garden"}]'::jsonb,
