UPDATE public.reading_lessons SET
  title_de = 'Das Frühstück',
  title_en = 'Breakfast',
  content_de = 'Es ist Sonntagmorgen, acht Uhr. Familie Krüger frühstückt zusammen. Auf dem Tisch sind frische Brötchen. Sie sind noch warm. Es gibt auch Butter, Marmelade und Honig. Käse und Wurst sind auch da.

Papa isst ein Brötchen mit Käse. Mama liebt Marmelade. Erdbeermarmelade ist ihre Lieblingsmarmelade. Die Kinder Emma und Paul essen Müsli mit Joghurt. Emma bekommt auch ein Ei.

Papa trinkt Kaffee, viel Kaffee! Mama trinkt Tee mit Zitrone. Die Kinder trinken Kakao und Orangensaft. Alle reden und lachen.

Das Sonntagsfrühstück dauert lange. Am Montag ist das Frühstück schnell. Aber heute ist Sonntag. Guten Appetit!',
  content_en = 'It is Sunday morning, eight o''clock. The Krüger family has breakfast together. On the table there are fresh bread rolls. They are still warm. There are also butter, jam and honey. Cheese and cold cuts are there too.

Dad eats a roll with cheese. Mom loves jam. Strawberry jam is her favorite jam. The children Emma and Paul eat muesli with yogurt. Emma also gets an egg.

Dad drinks coffee, a lot of coffee! Mom drinks tea with lemon. The children drink cocoa and orange juice. Everyone talks and laughs.

The Sunday breakfast takes a long time. On Monday breakfast is quick. But today is Sunday. Enjoy your meal!',
  key_vocabulary = '[{"de":"das Frühstück","en":"breakfast"},{"de":"das Brötchen","en":"bread roll"},{"de":"die Marmelade","en":"jam"},{"de":"der Honig","en":"honey"},{"de":"der Käse","en":"cheese"},{"de":"das Ei","en":"egg"},{"de":"der Kaffee","en":"coffee"},{"de":"der Tee","en":"tea"}]'::jsonb,
  questions = '[{"question_de":"Was isst Papa?","question_en":"What does Dad eat?","answer_de":"Papa isst ein Brötchen mit Käse.","answer_en":"Dad eats a roll with cheese."},{"question_de":"Was trinken die Kinder?","question_en":"What do the children drink?","answer_de":"Die Kinder trinken Kakao und Orangensaft.","answer_en":"The children drink cocoa and orange juice."},{"question_de":"Wie ist das Frühstück am Montag?","question_en":"What is breakfast like on Monday?","answer_de":"Am Montag ist das Frühstück schnell.","answer_en":"On Monday breakfast is quick."},{"question_de":"Was liebt Mama?","question_en":"What does Mom love?","answer_de":"Mama liebt Marmelade.","answer_en":"Mom loves jam."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Mama trinkt Kaffee.","statement_en":"Mom drinks coffee.","answer":"falsch","explanation_de":"Mama trinkt Tee, Papa trinkt viel Kaffee."},{"type":"rf","statement_de":"Die Kinder trinken Kaffee.","statement_en":"The children drink coffee.","answer":"falsch","explanation_de":"Die Kinder trinken Kakao und Orangensaft, keinen Kaffee."},{"type":"rf","statement_de":"Familie Krüger frühstückt am Sonntagmorgen.","statement_en":"The Krüger family has breakfast on Sunday morning.","answer":"richtig","explanation_de":"Der Text beginnt: \"Es ist Sonntagmorgen ... Familie Krüger frühstückt zusammen.\""},{"type":"rf","statement_de":"Am Montag ist das Frühstück schnell.","statement_en":"On Monday breakfast is quick.","answer":"richtig","explanation_de":"Der Text sagt das direkt am Ende."}]'::jsonb,
  word_count = 95,
  estimated_reading_time = 2
WHERE id = '921518d9-e638-4468-b3d5-c18b10b31625'
  AND checks IS NULL; -- idempotency guard: a re-run after this migration has
