UPDATE public.reading_lessons SET
  title_de = 'Farben und Kleidung',
  title_en = 'Colors and Clothes',
  content_de = 'Heute ist Sonntag. Familie Weber macht ein Foto. Papa trägt ein Hemd und eine Hose. Das Hemd ist weiß, die Hose ist blau.

Mama hat ein rotes Kleid. Ihre Schuhe sind auch rot.

Tim ist acht Jahre alt. Er hat ein T-Shirt und eine Jacke. Sein T-Shirt ist grün, seine Jacke ist gelb.

Lisa liebt Schwarz. Ihr Pullover ist schwarz. Ihre Mütze ist auch schwarz. Mama fragt: „Ist Schwarz nicht langweilig?“ Lisa sagt: „Nein, Schwarz ist cool!“

Oma hat eine Bluse und einen Rock. Die Bluse ist lila, der Rock ist grau. Opa hat einen Mantel und einen Hut.

Alle lachen. Das Foto ist bunt und schön.',
  content_en = 'Today is Sunday. The Weber family takes a photo. Dad wears a shirt and trousers. The shirt is white, the trousers are blue.

Mom has a red dress. Her shoes are red too.

Tim is eight years old. He has a T-shirt and a jacket. His T-shirt is green, his jacket is yellow.

Lisa loves black. Her sweater is black. Her beanie is black too. Mom asks: "Isn''t black boring?" Lisa says: "No, black is cool!"

Grandma has a blouse and a skirt. The blouse is purple, the skirt is grey. Grandpa has a coat and a hat.

Everyone laughs. The photo is colorful and beautiful.',
  key_vocabulary = '[{"de":"tragen","en":"to wear"},{"de":"das Hemd, -en","en":"shirt"},{"de":"die Hose, -n","en":"trousers, pants"},{"de":"das Kleid, -er","en":"dress"},{"de":"die Jacke, -n","en":"jacket"},{"de":"der Pullover, -","en":"sweater"},{"de":"die Bluse, -n","en":"blouse"},{"de":"der Mantel, Mäntel","en":"coat"}]'::jsonb,
