  checks = '[{"type":"rf","statement_de":"Lisa liebt die Farbe Weiß.","statement_en":"Lisa loves the color white.","answer":"falsch","explanation_de":"Lisa liebt Schwarz, nicht Weiß."},{"type":"rf","statement_de":"Mamas Kleid ist rot.","statement_en":"Mom''s dress is red.","answer":"richtig","explanation_de":"Der Text sagt: \"Mama hat ein rotes Kleid.\""},{"type":"rf","statement_de":"Tims Jacke ist blau.","statement_en":"Tim''s jacket is blue.","answer":"falsch","explanation_de":"Tims Jacke ist gelb, nicht blau."},{"type":"rf","statement_de":"Opa hat einen Mantel und einen Hut.","statement_en":"Grandpa has a coat and a hat.","answer":"richtig","explanation_de":"Der Text sagt das direkt."}]'::jsonb,
