UPDATE public.reading_lessons SET
  title_de = 'Das Wetter heute',
  title_en = 'The Weather Today',
  content_de = 'Heute ist Montag. Das Wetter ist schön. Die Sonne scheint. Der Himmel ist blau. Es ist warm, fast 25 Grad. Viele Leute sind im Park.

Im Frühling regnet es oft. Dann brauchen alle einen Regenschirm. Alles ist grün, und die Blumen blühen.

Der Sommer ist heiß. Manchmal sind es über 30 Grad. Dann schwimmen die Kinder im See.

Im Herbst ist es windig und kühl. Die Blätter sind gelb, rot und braun.

Der Winter ist kalt. Manchmal schneit es. Der Schnee ist weiß. Die Kinder spielen im Schnee.

Und heute? Heute ist das Wetter perfekt. Anna und Tom machen ein Picknick im Park. Sie haben Glück!',
  content_en = 'Today is Monday. The weather is beautiful. The sun is shining. The sky is blue. It is warm, almost 25 degrees. Many people are in the park.

In spring it often rains. Then everyone needs an umbrella. Everything is green, and the flowers are blooming.

Summer is hot. Sometimes it is over 30 degrees. Then the children swim in the lake.

In autumn it is windy and cool. The leaves are yellow, red and brown.

Winter is cold. Sometimes it snows. The snow is white. The children play in the snow.

And today? Today the weather is perfect. Anna and Tom are having a picnic in the park. They are lucky!',
  key_vocabulary = '[{"de":"das Wetter (nur Sg.)","en":"weather"},{"de":"die Sonne, -n","en":"sun"},{"de":"der Himmel (nur Sg.)","en":"sky"},{"de":"der Frühling, -e","en":"spring"},{"de":"der Regenschirm, -e","en":"umbrella"},{"de":"der Sommer, -","en":"summer"},{"de":"der Herbst, -e","en":"autumn"},{"de":"der Winter, -","en":"winter"}]'::jsonb,
  questions = '[{"question_de":"Wie ist das Wetter heute?","question_en":"What is the weather like today?","answer_de":"Das Wetter ist heute schön und warm.","answer_en":"The weather is beautiful and warm today."},{"question_de":"Was brauchen die Leute im Frühling?","question_en":"What do people need in spring?","answer_de":"Im Frühling brauchen alle einen Regenschirm.","answer_en":"In spring everyone needs an umbrella."},{"question_de":"Wie ist der Winter?","question_en":"What is winter like?","answer_de":"Der Winter ist kalt.","answer_en":"Winter is cold."},{"question_de":"Was machen Anna und Tom heute?","question_en":"What are Anna and Tom doing today?","answer_de":"Anna und Tom machen ein Picknick im Park.","answer_en":"Anna and Tom are having a picnic in the park."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Heute scheint die Sonne.","statement_en":"The sun is shining today.","answer":"richtig","explanation_de":"Der Text sagt: \"Die Sonne scheint.\""},{"type":"rf","statement_de":"Im Winter ist es heiß.","statement_en":"It is hot in winter.","answer":"falsch","explanation_de":"Der Winter ist kalt, nicht heiß."},{"type":"rf","statement_de":"Anna und Tom sind heute zu Hause.","statement_en":"Anna and Tom are at home today.","answer":"falsch","explanation_de":"Sie machen ein Picknick im Park, sie sind nicht zu Hause."},{"type":"rf","statement_de":"Im Herbst sind die Blätter gelb, rot und braun.","statement_en":"In autumn the leaves are yellow, red and brown.","answer":"richtig","explanation_de":"Der Text sagt das direkt."}]'::jsonb,
  word_count = 106,
  estimated_reading_time = 2
WHERE id = 'b6caaf77-8e51-4884-b065-174a95145750'
  AND checks IS NULL; -- idempotency guard: a re-run after this migration has
                       -- already applied is a no-op

UPDATE public.reading_lessons SET
  title_de = 'Mein Tag',
  title_en = 'My Day',
  content_de = 'Das ist mein Tag. Mein Wecker klingelt um 6:30 Uhr. Ich stehe auf. Ich dusche und putze meine Zähne.

Um 7 Uhr mache ich Frühstück. Ich esse Brot mit Marmelade. Ich trinke eine Tasse Kaffee.

Um 7:45 Uhr verlasse ich das Haus. Ich fahre mit der U-Bahn zur Arbeit. Die Fahrt dauert 25 Minuten.

Ich arbeite von 9 bis 17 Uhr im Büro. Ich bin Sekretärin. Ich schreibe E-Mails und telefoniere.

Dann gehe ich einkaufen. Ich kaufe Obst und Brot.

Um 19 Uhr koche ich Abendessen. Ich koche gern Pasta. Danach räume ich die Küche auf.

Am Abend rufe ich meine Familie an. Um 23 Uhr gehe ich ins Bett.',
  content_en = 'This is my day. My alarm clock rings at 6:30. I get up. I shower and brush my teeth.

At 7 o''clock I make breakfast. I eat bread with jam. I drink a cup of coffee.

At 7:45 I leave the house. I take the subway to work. The journey takes 25 minutes.

I work from 9 to 5 in the office. I am a secretary. I write emails and make phone calls.

Then I go shopping. I buy fruit and bread.

At 7 PM I cook dinner. I like to cook pasta. After that I clean up the kitchen.

In the evening I call my family. At 11 PM I go to bed.',
  key_vocabulary = '[{"de":"der Wecker","en":"alarm clock"},{"de":"aufstehen","en":"to get up"},{"de":"das Frühstück","en":"breakfast"},{"de":"die U-Bahn","en":"subway"},{"de":"das Büro","en":"office"},{"de":"einkaufen","en":"to go shopping"},{"de":"das Abendessen","en":"dinner"},{"de":"aufräumen","en":"to tidy up"}]'::jsonb,
  questions = '[{"question_de":"Wann klingelt der Wecker?","question_en":"When does the alarm clock ring?","answer_de":"Der Wecker klingelt um 6:30 Uhr.","answer_en":"The alarm clock rings at 6:30."},{"question_de":"Was ist die Person von Beruf?","question_en":"What is the person''s profession?","answer_de":"Sie ist Sekretärin.","answer_en":"She is a secretary."},{"question_de":"Wie lange dauert die Fahrt zur Arbeit?","question_en":"How long does the journey to work take?","answer_de":"Die Fahrt dauert 25 Minuten.","answer_en":"The journey takes 25 minutes."},{"question_de":"Wann geht die Person ins Bett?","question_en":"When does the person go to bed?","answer_de":"Sie geht um 23 Uhr ins Bett.","answer_en":"She goes to bed at 11 PM."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Die Person arbeitet im Supermarkt.","statement_en":"The person works at the supermarket.","answer":"falsch","explanation_de":"Sie arbeitet im Büro und ist Sekretärin."},{"type":"rf","statement_de":"Der Wecker klingelt um 6:30 Uhr.","statement_en":"The alarm clock rings at 6:30.","answer":"richtig","explanation_de":"Der Text sagt das am Anfang."},{"type":"rf","statement_de":"Die Fahrt zur Arbeit dauert 25 Minuten.","statement_en":"The journey to work takes 25 minutes.","answer":"richtig","explanation_de":"Der Text sagt das direkt."},{"type":"rf","statement_de":"Am Abend geht die Person sofort ins Bett.","statement_en":"In the evening the person goes to bed right away.","answer":"falsch","explanation_de":"Sie kocht zuerst, ruft die Familie an und geht erst um 23 Uhr ins Bett."}]'::jsonb,
