UPDATE public.reading_lessons SET
  title_de = 'Im Supermarkt',
  title_en = 'At the Supermarket',
  content_de = 'Samstag ist Einkaufstag. Anna ist im Supermarkt. Sie hat eine Liste und einen Einkaufswagen.

Zuerst kauft sie Obst und Gemüse. Die Äpfel sind heute im Angebot. Ein Kilo kostet nur zwei Euro. Anna kauft auch Bananen und Tomaten.

Dann braucht sie Milch, Butter und Käse. Das Brot ist ganz frisch. Anna kauft zwei Brötchen und ein Brot. Sie sucht noch Nudeln, Reis und Eier.

Der Einkaufswagen ist jetzt voll. An der Kasse ist eine kleine Schlange. Anna wartet fünf Minuten. Die Kassiererin ist freundlich. Sie sagt: „Das macht 23,40 Euro, bitte.“

Anna bezahlt mit Karte. Sie packt alles in die Tasche. Der Einkauf ist fertig.',
  content_en = 'Saturday is shopping day. Anna is at the supermarket. She has a list and a shopping cart.

First she buys fruit and vegetables. The apples are on special offer today. One kilo costs only two euros. Anna also buys bananas and tomatoes.

Then she needs milk, butter and cheese. The bread is completely fresh. Anna buys two rolls and one loaf. She also looks for pasta, rice and eggs.

The shopping cart is full now. At the checkout there is a small queue. Anna waits five minutes. The cashier is friendly. She says: "That comes to 23.40 euros, please."

Anna pays by card. She packs everything into her bag. The shopping is done.',
  key_vocabulary = '[{"de":"der Supermarkt, -märkte","en":"supermarket"},{"de":"der Einkaufswagen, -","en":"shopping cart"},{"de":"die Liste, -n","en":"list"},{"de":"das Obst (nur Sg.)","en":"fruit"},{"de":"das Gemüse (nur Sg.)","en":"vegetables"},{"de":"der Apfel, Äpfel","en":"apple"},{"de":"das Angebot, -e","en":"offer"},{"de":"die Kasse, -n","en":"checkout"}]'::jsonb,
  questions = '[{"question_de":"Wann ist Einkaufstag?","question_en":"When is shopping day?","answer_de":"Samstag ist Einkaufstag.","answer_en":"Saturday is shopping day."},{"question_de":"Was kostet ein Kilo Äpfel?","question_en":"What does a kilo of apples cost?","answer_de":"Ein Kilo Äpfel kostet nur zwei Euro.","answer_en":"A kilo of apples costs only two euros."},{"question_de":"Wie lange wartet Anna an der Kasse?","question_en":"How long does Anna wait at the checkout?","answer_de":"Anna wartet fünf Minuten.","answer_en":"Anna waits five minutes."},{"question_de":"Wie bezahlt Anna?","question_en":"How does Anna pay?","answer_de":"Anna bezahlt mit Karte.","answer_en":"Anna pays by card."}]'::jsonb,
  checks = '[{"type":"rf","statement_de":"Samstag ist Einkaufstag.","statement_en":"Saturday is shopping day.","answer":"richtig","explanation_de":"Der Text beginnt genau damit."},{"type":"rf","statement_de":"Anna bezahlt mit Karte.","statement_en":"Anna pays by card.","answer":"richtig","explanation_de":"Der Text sagt das direkt."},{"type":"rf","statement_de":"Ein Kilo Äpfel kostet zehn Euro.","statement_en":"A kilo of apples costs ten euros.","answer":"falsch","explanation_de":"Ein Kilo kostet nur zwei Euro."},{"type":"rf","statement_de":"Anna wartet zwanzig Minuten an der Kasse.","statement_en":"Anna waits twenty minutes at the checkout.","answer":"falsch","explanation_de":"Anna wartet nur fünf Minuten."}]'::jsonb,
  word_count = 105,
  estimated_reading_time = 2
