SELECT
  'a1.1', 'Schilder und Aushänge (wie in der Prüfung, Teil 3)', 'Signs and notices (exam-style, part 3)', 'Prüfungsformat',
  'Schild 1 — An der Arztpraxis: Öffnungszeiten: Montag bis Freitag 8–12 Uhr und 15–18 Uhr. Samstag und Sonntag geschlossen.

Schild 2 — Im Supermarkt: Achtung: Der Supermarkt hat am Sonntag geschlossen. Bitte am Samstag einkaufen.

Schild 3 — An der Tür: Bitte die Schuhe im Haus ausziehen. Vielen Dank für Ihr Verständnis!

Schild 4 — Am Bahnhof: Zug nach München: Abfahrt 9:15 Uhr, Gleis 3. Der Zug fährt sonntags nicht.

Schild 5 — In der Schule: Der Deutschkurs beginnt um 9 Uhr. Bitte pünktlich kommen. Handys sind im Kurs verboten.', 'Sign 1 — At the doctor''s practice: Opening hours: Monday to Friday 8–12 and 15–18. Saturday and Sunday closed.

Sign 2 — At the supermarket: Notice: The supermarket is closed on Sunday. Please shop on Saturday.

Sign 3 — At the door: Please take off your shoes inside the house. Thank you for your understanding!

Sign 4 — At the train station: Train to Munich: departure 9:15, platform 3. The train does not run on Sundays.

Sign 5 — At the school: The German course starts at 9 o''clock. Please arrive on time. Phones are forbidden in the course.',
  '[{"de":"die Öffnungszeiten (nur Pl.)","en":"opening hours"},{"de":"geschlossen","en":"closed"},{"de":"der Schuh, -e","en":"shoe"},{"de":"der Zug, Züge","en":"train"},{"de":"das Gleis, -e","en":"platform, track"},{"de":"der Deutschkurs, -e","en":"German course"},{"de":"pünktlich","en":"on time"},{"de":"verboten","en":"forbidden"}]'::jsonb, '[]'::jsonb, '[{"type":"rf","statement_de":"Am Samstag ist die Praxis offen.","statement_en":"The practice is open on Saturday.","answer":"falsch","explanation_de":"Die Praxis ist Montag bis Freitag offen."},{"type":"rf","statement_de":"Der Sonntag ist kein Einkaufstag.","statement_en":"Sunday is not a shopping day.","answer":"richtig","explanation_de":"Das Schild sagt: Der Supermarkt ist am Sonntag geschlossen."},{"type":"rf","statement_de":"Im Haus trägt man Schuhe.","statement_en":"You wear shoes inside the house.","answer":"falsch","explanation_de":"Das Schild sagt: Bitte die Schuhe ausziehen."},{"type":"rf","statement_de":"Der Zug nach München fährt jeden Tag.","statement_en":"The train to Munich runs every day.","answer":"falsch","explanation_de":"Das Schild sagt: Der Zug fährt sonntags nicht."},{"type":"rf","statement_de":"Der Kurs beginnt am Morgen.","statement_en":"The course starts in the morning.","answer":"richtig","explanation_de":"9 Uhr ist am Morgen."}]'::jsonb,
  90, 1, 2, 10
